@Service
public class PaymentServiceClient {

    private final CircuitBreakerRegistry circuitBreakerRegistry;
    private final WebClient webClient;
    private CircuitBreaker circuitBreaker;

    public PaymentServiceClient(CircuitBreakerRegistry registry, WebClient webClient) {
        this.circuitBreakerRegistry = registry;
        this.webClient = webClient;

        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
            .failureRateThreshold(50.0f)
            .slowCallRateThreshold(75.0f)
            .slowCallDurationThreshold(Duration.ofMillis(500))
            .slidingWindowType(CircuitBreakerConfig.SlidingWindowType.TIME_BASED)
            .slidingWindowSize(10)
            .minimumNumberOfCalls(5)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .build();

        this.circuitBreaker = circuitBreakerRegistry.circuitBreaker("paymentService", config);
    }

    public Mono<PaymentResponse> processPayment(PaymentRequest request) {
        Supplier<Mono<PaymentResponse>> supplier = () -> webClient.post()
            .uri("/pay")
            .bodyValue(request)
            .retrieve()
            .bodyToMono(PaymentResponse.class);

        return Mono.defer(() -> supplier.get())
            .transformDeferred(CircuitBreakerOperator.of(circuitBreaker))
            .onErrorResume(CallNotPermittedException.class, ex -> fallbackPayment(request, ex));
    }

    private Mono<PaymentResponse> fallbackPayment(PaymentRequest request, Throwable t) {
        return Mono.just(new PaymentResponse("FAILED", "Circuit is open: " + t.getMessage()));
    }
}
